import fs from 'node:fs';import {createPublicClient,http,namehash,parseAbi} from '../enclave/node_modules/viem/_esm/index.js';
const c=createPublicClient({transport:http('https://ethereum-rpc.publicnode.com')});const name='enclavehost.eth',node=namehash(name);const resolver=await c.readContract({address:'0x00000000000C2E074eC69A0dFb2997BA6C7d2e1e',abi:parseAbi(['function resolver(bytes32) view returns (address)']),functionName:'resolver',args:[node]});const latest=await c.getBlockNumber();const logs=await c.getLogs({address:resolver,event:parseAbi(['event TextChanged(bytes32 indexed node,string indexed indexedKey,string key,string value)'])[0],args:{node},fromBlock:latest-9999n,toBlock:latest});const keys=[...new Set(logs.map(x=>x.args.key).filter(Boolean))];const text={};for(const key of keys){text[key]=await c.readContract({address:resolver,abi:parseAbi(['function text(bytes32,string) view returns (string)']),functionName:'text',args:[node,key]});}const out={name,node,resolver,fromBlock:String(latest-9999n),toBlock:String(latest),keys,text};fs.writeFileSync('outputs/ens-native-current.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out,null,2));
